def indices_to_torch_mask(
    width: int,
    indices: Iterable[int],
    device: torch.device | str | None = None,
    dtype: torch.dtype = torch.float32,
) -> torch.Tensor:
    mask = torch.zeros(width, device=device, dtype=dtype)
    idx = torch.as_tensor(list(indices), device=device, dtype=torch.long)

    if idx.numel() > 0:
        if torch.any(idx < 0) or torch.any(idx >= width):
            raise ValueError("Mask index out of bounds.")
        mask[idx] = 1.0

    return mask

def load_mask_records(mask_indices_json: str | Path) -> dict:
    with open(mask_indices_json, "r", encoding="utf-8") as f:
        obj = json.load(f)
    return {rec["volume_id"]: rec for rec in obj["records"]}
